import streamlit as st
import streamlit.components.v1 as components
import base64

st.set_page_config(
    page_title="Finora",
    page_icon="📊",
    layout="wide",
    initial_sidebar_state="collapsed"
)

# Remove Streamlit's default chrome so Finora fills the page.
st.markdown("""
<style>
    #MainMenu {visibility: hidden;}
    footer {visibility: hidden;}
    header {visibility: hidden;}
    .stApp {background: #f4faf6;}
    .block-container {
        padding: 0 !important;
        max-width: 100% !important;
    }
    iframe {
        border: 0 !important;
    }
</style>
""", unsafe_allow_html=True)

FINORA_B64 = """"""
finora_html = base64.b64decode(FINORA_B64).decode("utf-8")

components.html(
    finora_html,
    height=1200,
    scrolling=True
)
